import{_ as r,C as n,o as e,c as s,a2 as a,b as i,w as l,a as d,E as g,a3 as c}from"./chunks/framework.CZGNF-7T.js";const D=JSON.parse('{"title":"업무실행내역 (Activity Log)","description":"","frontmatter":{},"headers":[],"relativePath":"work-manage/activity.md","filePath":"work-manage/activity.md","lastUpdated":1788456872000}'),E={name:"work-manage/activity.md"};function B(m,t,h,C,A,f){const o=n("Mermaid");return e(),s("div",null,[t[1]||(t[1]=a('<h1 id="업무실행내역-activity-log" tabindex="-1">업무실행내역 (Activity Log) <a class="header-anchor" href="#업무실행내역-activity-log" aria-label="Permalink to &quot;업무실행내역 (Activity Log)&quot;">​</a></h1><blockquote><p><strong>업무실행내역</strong> 페이지는 워크스페이스(또는 전사) 내에서 발생한 모든 업무 생성, 상태 변경, 회의록 등록, 문서 공유 등의 협업 활동을 시간 순으로 기록하고 모니터링하는 <strong>실시간 활동 타임라인 피드</strong>입니다.</p></blockquote><h2 id="_1-화면-개요" tabindex="-1">1. 화면 개요 <a class="header-anchor" href="#_1-화면-개요" aria-label="Permalink to &quot;1. 화면 개요&quot;">​</a></h2><p>누가, 언제, 어떤 업무나 의사결정을 수행했는지 한눈에 파악할 수 있으며, 상세 페이지로 이동하지 않고도 핵심 내용을 파악할 수 있도록 <strong>113자 마크다운 컨텐츠 요약</strong>을 제공합니다.</p>',4)),(e(),i(c,null,{default:l(()=>[g(o,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20%ED%99%9C%EB%8F%99%EB%B0%9C%EC%83%9D%EC%9B%90%20%5B%226%EB%8C%80%20%ED%99%9C%EB%8F%99%20%EB%B0%9C%EC%83%9D%EC%9B%90%22%5D%0A%20%20%20%20%20%20%20%20A%5B%22%F0%9F%8E%AF%20%EC%97%85%EB%AC%B4%20%EC%83%9D%EC%84%B1%2F%EB%B3%80%EA%B2%BD%22%5D%0A%20%20%20%20%20%20%20%20B%5B%22%F0%9F%92%AC%20%EC%97%85%EB%AC%B4%20%EB%8C%93%EA%B8%80%2F%EC%9D%98%EA%B2%AC%22%5D%0A%20%20%20%20%20%20%20%20C%5B%22%F0%9F%93%9D%20%ED%9A%8C%EC%9D%98%EB%A1%9D%20%EB%93%B1%EB%A1%9D%22%5D%0A%20%20%20%20%20%20%20%20D%5B%22%F0%9F%93%A2%20%EA%B3%B5%EC%A7%80%EC%82%AC%ED%95%AD%22%5D%0A%20%20%20%20%20%20%20%20E%5B%22%F0%9F%93%81%20%EB%AC%B8%EC%84%9C%20%EC%97%85%EB%A1%9C%EB%93%9C%22%5D%0A%20%20%20%20%20%20%20%20F%5B%22%E2%9C%8D%EF%B8%8F%20%EA%B2%8C%EC%8B%9C%ED%8C%90%20%EA%B8%80%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20A%20%26%20B%20%26%20C%20%26%20D%20%26%20E%20%26%20F%20--%3E%20G%5B%22%E2%8F%B1%EF%B8%8F%20%EC%97%85%EB%AC%B4%EC%8B%A4%ED%96%89%EB%82%B4%EC%97%AD%20%ED%94%BC%EB%93%9C%3Cbr%3E(10%EC%9D%BC%20%EB%A1%A4%EB%A7%81%20%ED%83%80%EC%9E%84%EB%9D%BC%EC%9D%B8)%22%5D%0A%20%20%20%20G%20--%3E%20H%5B%22%F0%9F%94%8D%20%EC%82%AC%EC%9A%A9%EC%9E%90%2F%EB%AA%A8%EB%93%88%EB%B3%84%20%ED%95%84%ED%84%B0%EB%A7%81%20%26%20%EC%83%81%EC%84%B8%20%EC%9D%B4%EB%8F%99%22%5D%0A"})]),fallback:l(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<p>기본적으로 기준일로부터 <strong>최근 10일간의 활동 기록</strong>을 일자별(<code>오늘</code> 또는 <code>YYYY/MM/DD</code>)로 묶어 제공합니다.</p><h2 id="_2-주요-기능-안내" tabindex="-1">2. 주요 기능 안내 <a class="header-anchor" href="#_2-주요-기능-안내" aria-label="Permalink to &quot;2. 주요 기능 안내&quot;">​</a></h2><h3 id="📅-10일-단위-기간별-조회-및-네비게이션" tabindex="-1">📅 10일 단위 기간별 조회 및 네비게이션 <a class="header-anchor" href="#📅-10일-단위-기간별-조회-및-네비게이션" aria-label="Permalink to &quot;📅 10일 단위 기간별 조회 및 네비게이션&quot;">​</a></h3><ul><li><strong>조회 기간 표시</strong>: 상단에 현재 조회 중인 날짜 범위(<code>YYYY/MM/DD부터 YYYY/MM/DD까지</code>)가 이탤릭체로 표시됩니다.</li><li><strong>기간 이동 버튼</strong>: <ul><li><strong><code>[« 뒤로]</code></strong>: 현재 기준일로부터 10일 이전 과거 기록으로 이동합니다.</li><li><strong><code>[다음 »]</code></strong>: 10일 이후 미래 기록으로 이동하며, 오늘 날짜를 초과하지 않도록 자동 제한됩니다.</li></ul></li><li><strong>기준일 직접 지정</strong>: 우측 설정 패널의 <strong>[10일 기록]</strong> 캘린더에서 특정 일자를 선택하면 해당 날짜를 종료일로 하는 10일간의 기록을 즉시 조회합니다.</li></ul><h3 id="👥-사용자별-활동-필터링" tabindex="-1">👥 사용자별 활동 필터링 <a class="header-anchor" href="#👥-사용자별-활동-필터링" aria-label="Permalink to &quot;👥 사용자별 활동 필터링&quot;">​</a></h3><ul><li>우측 사이드바의 <strong>[사용자]</strong> 드롭다운을 통해 특정 팀원의 활동만 선별 조회할 수 있습니다.</li><li><strong><code>&lt;&lt; 나 &gt;&gt;</code></strong> 옵션을 선택하면 본인이 생성하거나 수정한 활동 내역만 빠르게 확인할 수 있습니다.</li></ul><h3 id="🗂️-6대-활동-유형별-모듈-필터링" tabindex="-1">🗂️ 6대 활동 유형별 모듈 필터링 <a class="header-anchor" href="#🗂️-6대-활동-유형별-모듈-필터링" aria-label="Permalink to &quot;🗂️ 6대 활동 유형별 모듈 필터링&quot;">​</a></h3><p>보고자 하는 활동의 종류만 선택하여 피드를 간소화할 수 있으며, 설정된 필터는 브라우저에 자동 저장되어 재접속 시에도 유지됩니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">활동 유형</th><th style="text-align:center;">식별 아이콘</th><th style="text-align:left;">제공되는 주요 요약 정보</th><th style="text-align:left;">연관 매뉴얼</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>업무</strong></td><td style="text-align:center;"><i class="mdi mdi-folder-edit"></i></td><td style="text-align:left;">업무 번호, 트래커, 제목, 변경 상태 및 <strong>업무 설명 요약</strong> (완료 시 녹색 아이콘)</td><td style="text-align:left;"><a href="/work-manage/issue.html">업무 관리</a></td></tr><tr><td style="text-align:left;"><strong>의견</strong></td><td style="text-align:center;"><i class="mdi mdi-comment-text-multiple"></i></td><td style="text-align:left;">업무 번호, 제목 및 등록된 <strong>댓글(Comment) 내용 요약</strong></td><td style="text-align:left;"><a href="/work-manage/issue.html">업무 이력</a></td></tr><tr><td style="text-align:left;"><strong>회의</strong></td><td style="text-align:center;"><i class="mdi mdi-account-group"></i></td><td style="text-align:left;">회의 번호, 제목, 진행 상태 및 <strong>회의 의제(Agenda) 요약</strong></td><td style="text-align:left;"><a href="/work-manage/meeting.html">회의록 관리</a></td></tr><tr><td style="text-align:left;"><strong>공지</strong></td><td style="text-align:center;"><i class="mdi mdi-message-badge"></i></td><td style="text-align:left;">공지 제목 및 등록된 <strong>공지 본문 요약(Summary)</strong></td><td style="text-align:left;"><a href="/work-manage/news.html">공지 관리</a></td></tr><tr><td style="text-align:left;"><strong>문서</strong></td><td style="text-align:center;"><i class="mdi mdi-file-document"></i></td><td style="text-align:left;">문서 제목 및 <strong>문서 본문 설명 요약</strong></td><td style="text-align:left;"><a href="/work-manage/docs.html">문서 관리</a></td></tr><tr><td style="text-align:left;"><strong>글</strong></td><td style="text-align:center;"><i class="mdi mdi-text-box-multiple"></i></td><td style="text-align:left;">게시판 명칭, 게시글 제목 및 <strong>게시글 본문 내용 요약</strong></td><td style="text-align:left;"><a href="/work-manage/forum.html">게시판 포럼</a></td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>유형 단독 선택(Pick Sort) 기능</strong>: 체크박스 우측의 텍스트(예: <code>업무</code>, <code>회의</code>, <code>공지</code> 등)를 클릭하면 다른 체크박스가 모두 해제되고 <strong>해당 유형 하나만 즉시 단독 필터링</strong>되어 매우 편리합니다.</p></div><h3 id="🌲-하위-워크스페이스-포함-조회" tabindex="-1">🌲 하위 워크스페이스 포함 조회 <a class="header-anchor" href="#🌲-하위-워크스페이스-포함-조회" aria-label="Permalink to &quot;🌲 하위 워크스페이스 포함 조회&quot;">​</a></h3><ul><li>상위 워크스페이스에서 작업 중인 경우, 우측 패널의 <strong>[하위 프로젝트/워크스페이스]</strong> 체크박스를 활성화하면 하위 조직 및 서브 프로젝트에서 발생한 활동까지 통합 타임라인으로 확인할 수 있습니다.</li></ul><h2 id="_3-화면-이용-팁" tabindex="-1">3. 화면 이용 팁 <a class="header-anchor" href="#_3-화면-이용-팁" aria-label="Permalink to &quot;3. 화면 이용 팁&quot;">​</a></h2><ul><li><strong>마크다운 서식 미리보기</strong>: 모든 활동 요약 문구는 마크다운 렌더링이 적용되어 굵은 글씨, 목록 등이 정돈된 형태로 깔끔하게 표시됩니다.</li><li><strong>상세 페이지 원클릭 이동</strong>: 활동 항목의 제목(업무 번호, 회의 제목, 문서명 등)을 클릭하면 해당 상세 페이지로 즉시 이동하며, 댓글 클릭 시 해당 댓글 위치(<code>#note-ID</code>)로 자동 스크롤됩니다.</li><li><strong>작성자 프로필 조회</strong>: 작성자 이름을 클릭하면 해당 사용자의 정보 및 활동 프로필 화면으로 이동합니다.</li></ul>',14))])}const x=r(E,[["render",B]]);export{D as __pageData,x as default};
